sealed class AdmissionResponse: Disposable  {
    
    data class Status(
        val `status`: org.arachne.core.runtime.AdmissionStatus) : AdmissionResponse()
        
    {
        

        companion object
    }
    
    data class Granted(
        val `grant`: org.arachne.core.runtime.AdmissionGrant) : AdmissionResponse()
        
    {
        

        companion object
    }
    

    
    @Suppress("UNNECESSARY_SAFE_CALL") // codegen is much simpler if we unconditionally emit safe calls here
    override fun destroy() {
        when(this) {
            is AdmissionResponse.Status -> {
                
    Disposable.destroy(
        this.`status`
    )
                
            }
            is AdmissionResponse.Granted -> {
                
    Disposable.destroy(
        this.`grant`
    )
                
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAdmissionResponse : FfiConverterRustBuffer<AdmissionResponse>{
    override fun read(buf: ByteBuffer): AdmissionResponse {
        return when(buf.getInt()) {
            1 -> AdmissionResponse.Status(
                FfiConverterTypeAdmissionStatus.read(buf),
                )
            2 -> AdmissionResponse.Granted(
                FfiConverterTypeAdmissionGrant.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: AdmissionResponse) = when(value) {
        is AdmissionResponse.Status -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
