/**
 * Typealias from the type name used in the UDL file to the builtin type.  This
 * is needed because the UDL type name is used in function/method signatures.
 * It's also what we have an external type that references a custom type.
 */
public typealias FreshnessAnchor = kotlin.ByteArray
public typealias FfiConverterTypeFreshnessAnchor = FfiConverterByteArray







object ApiExceptionExternalErrorHandler : UniffiRustCallStatusErrorHandler<ApiException> {
    override fun lift(error_buf: RustBuffer.ByValue): ApiException =
        org.arachne.core.api.ApiException.ErrorHandler.lift(
            RustBufferApiError.ByValue().apply {
                capacity = error_buf.capacity
                len = error_buf.len
                data = error_buf.data
            }
        )
}


















        /**
         * Start with the profile defaults; attach a persistent key and storage before
         * opening a workspace client.
         */ fun `defaultClientConfig`(`network`: Network): ClientConfig {
            return FfiConverterTypeClientConfig.lift(
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_arachne_runtime_fn_func_default_client_config(
    
        FfiConverterTypeNetwork.lower(`network`),_status)
}
    )
    }
    

